// Weight-streaming bf16 GEMM body: out[m, N] = a[m, K] @ b[N, K].T for one fixed (N, K), m <= MT.
#pragma once

#include <hip/hip_runtime.h>

#include <cstdint>

extern "C" __device__ uint64_t lmhead_dispatch_id() __asm("llvm.amdgcn.dispatch.id");

namespace lmhead {

typedef __attribute__((ext_vector_type(8))) __bf16 bf16x8;
typedef __attribute__((ext_vector_type(4))) float f32x4;
typedef __attribute__((ext_vector_type(4))) int i32x4;
typedef __attribute__((ext_vector_type(2))) unsigned u32x2;

__device__ __forceinline__ i32x4 make_rsrc(const void* base, uint32_t bytes) {
    const uint64_t p = reinterpret_cast<uint64_t>(base);
    i32x4 r;
    r.x = __builtin_amdgcn_readfirstlane(static_cast<int>(static_cast<uint32_t>(p)));
    r.y = __builtin_amdgcn_readfirstlane(static_cast<int>(static_cast<uint32_t>(p >> 32)));
    r.z = static_cast<int>(bytes);
    r.w = 0x00020000;
    return r;
}

// 16 bytes per lane from rsrc + voff + soff into LDS at m0 + lane * 16 (nt: streamed, evicted
// first); counted by vmcnt only, so the compiler never waits on it.
template <bool NT>
__device__ __forceinline__ void dma16(uint32_t lds, uint32_t voff, i32x4 rsrc, uint32_t soff) {
    if constexpr (NT) {
        asm volatile("s_mov_b32 m0, %0\n\ts_nop 0\n\tbuffer_load_dwordx4 %1, %2, %3 offen nt lds"
                     ::"s"(lds), "v"(voff), "s"(rsrc), "s"(soff) : "memory", "m0");
    } else {
        asm volatile("s_mov_b32 m0, %0\n\ts_nop 0\n\tbuffer_load_dwordx4 %1, %2, %3 offen lds"
                     ::"s"(lds), "v"(voff), "s"(rsrc), "s"(soff) : "memory", "m0");
    }
}

template <int VM>
__device__ __forceinline__ void wait_vm() {
    static_assert(VM >= 0 && VM < 64, "vmcnt range");
    __builtin_amdgcn_s_waitcnt((VM & 15) | ((VM >> 4) << 14) | (7 << 4) | (15 << 8));
}

// wait_vm<rem * L>() for a runtime rem in [0, R]
template <int L, int R>
__device__ __forceinline__ void wait_tail(int rem) {
    if constexpr (R > 0) {
        if (rem >= R) {
            wait_vm<R * L>();
            return;
        }
        wait_tail<L, R - 1>(rem);
    } else {
        wait_vm<0>();
    }
}

// a wave that issues L or L - 1 DMAs per stage waits until at most min(R, rem) stages are pending
template <int L, int R>
__device__ __forceinline__ void wait_stages(bool short_wave, int rem) {
    if constexpr (L > 1) {
        if (short_wave) {
            wait_tail<L - 1, R>(rem);
            return;
        }
    }
    wait_tail<L, R>(rem);
}

__device__ __forceinline__ void barrier_lds() {
    asm volatile("s_waitcnt lgkmcnt(0)\n\ts_barrier" ::: "memory");
}

__device__ __forceinline__ uint32_t pack_bf16x2(float lo, float hi) {
    const uint32_t a = __builtin_bit_cast(uint32_t, lo);
    const uint32_t b = __builtin_bit_cast(uint32_t, hi);
    const uint32_t ra = (a + 0x7fffu + ((a >> 16) & 1u)) >> 16;
    const uint32_t rb = (b + 0x7fffu + ((b >> 16) & 1u)) >> 16;
    return ra | (rb << 16);
}

// G workgroups: G / SK tiles of contiguous b rows (8-row groups split evenly, NT rows at most)
// times SK slices of K. b and a go to LDS by DMA in BK-wide K tiles, b through an SB-deep ring
// issued by the first W - WA waves and a through an SA-deep ring issued by the last WA waves, so
// each wave's vmcnt covers one stream only and b can run further ahead than a. The product is
// computed transposed (MFMA rows are b rows); WM x WN waves each own MS m-blocks x NSW n-blocks
// of 16. Consecutive tiles start K at a rotated phase so that workgroups do not hit the same HBM
// channels together. The SK slices of a tile run on one XCD (workgroups t + 8 j); each finalizes
// every SK-th accumulator block, adding the others' fp32 partials in slice order, so the result
// does not depend on arrival order.
template <int N_, int K_, int MT_, int G_, int SK_, int SB_, int SA_, int WM_, int WN_, int WA_, int KROT_ = 8>
struct Cfg {
    static constexpr int N = N_, K = K_, MT = MT_, G = G_, SK = SK_, BK = 64, SB = SB_, SA = SA_;
    static constexpr int WM = WM_, WN = WN_, WA = WA_, KROT = KROT_;
    static constexpr int TILES = G / SK;
    static constexpr int NT = (N / 8 + TILES - 1) / TILES * 8;
    static constexpr int CH = BK / 8;
    static constexpr int NTL = (NT * CH + 63) / 64 * 64 / CH;
    static constexpr int NS = (NT + 15) / 16;
    static constexpr int NSW = (NS + WN - 1) / WN;
    static constexpr int MS = MT / 16 / WM;
    static constexpr int NB = MS * NSW;
    static constexpr int W = WM * WN;
    static constexpr int T = 64 * W;
    static constexpr int WB = W - WA;
    static constexpr int KT = K / SK / BK;
    static constexpr int KSTEPS = BK / 32;
    static constexpr int IB = NTL * CH / 64;
    static constexpr int IA = MT * CH / 64;
    static constexpr int LB = (IB + WB - 1) / WB;
    static constexpr int LA = (IA + WA - 1) / WA;
    static constexpr int STB = NTL * CH * 16;
    static constexpr int STA = MT * CH * 16;
    static constexpr int LDS = SB * STB + SA * STA;
    static_assert(MT % (16 * WM) == 0 && NTL * CH % 64 == 0 && MT * CH % 64 == 0, "tiling");
    static_assert(WA >= 1 && WB >= 1 && W <= 16, "wave roles");
    static_assert(N % 8 == 0 && TILES <= N / 8, "8-row groups");
    static_assert(SK == 1 || G % (8 * SK) == 0, "split-K groups share an XCD");
    static_assert(K % (SK * BK) == 0 && KT >= SB && KT >= SA && SA >= 2 && SB >= 2, "pipeline depth");
    static_assert((SB - 2) * LB < 64 && (SA - 2) * LA < 64, "vmcnt");
    static_assert(LDS <= 160 * 1024, "LDS");
};

template <class C>
__global__ __launch_bounds__(C::T) void gemm_kernel(const __bf16* __restrict__ a, const __bf16* __restrict__ b,
                                                     __bf16* __restrict__ out, f32x4* __restrict__ ws,
                                                     uint64_t* __restrict__ flags, int m) {
    constexpr int N = C::N, K = C::K, BK = C::BK, SB = C::SB, SA = C::SA, CH = C::CH;
    constexpr int KT = C::KT, MS = C::MS, NSW = C::NSW, SK = C::SK;
    __shared__ __attribute__((aligned(1024))) char smem[C::LDS];

    const int lane = threadIdx.x & 63;
    const int wave = __builtin_amdgcn_readfirstlane(threadIdx.x >> 6);
    const int wm = wave % C::WM;
    const int wn = wave / C::WM;
    const int bid = blockIdx.x;
    const int tile = SK == 1 ? bid : bid / (8 * SK) * 8 + bid % 8;
    const int kh = SK == 1 ? 0 : bid / 8 % SK;
    const int r0 = (tile * (N / 8) / C::TILES) * 8;
    const int nr = ((tile + 1) * (N / 8) / C::TILES) * 8 - r0;
    const int k0 = kh * (K / SK);

    const bool b_wave = wave < C::WB;
    const int rw = b_wave ? wave : wave - C::WB;
    const int nw = b_wave ? C::WB : C::WA;
    const int ni = b_wave ? C::IB : C::IA;
    const bool short_wave = rw + nw * ((b_wave ? C::LB : C::LA) - 1) >= ni;
    const i32x4 rsrc = b_wave ? make_rsrc(b + k0, static_cast<uint32_t>(N) * K * 2)
                              : make_rsrc(a + k0, static_cast<uint32_t>(m) * K * 2);
    const uint32_t lds0 = static_cast<uint32_t>(reinterpret_cast<uintptr_t>(smem));
    const uint32_t lds_a = lds0 + SB * C::STB;

    // DMA i of a stage covers 64 16-byte chunks of consecutive rows, each row's chunks swizzled.
    // b rows >= nr reload row nr - 1 and a rows >= m reload row m - 1; they are never stored.
    constexpr int L = C::LB > C::LA ? C::LB : C::LA;
    uint32_t voff[L];
#pragma unroll
    for (int j = 0; j < L; ++j) {
        const int u = (rw + nw * j) * 64 + lane;
        const int row = u / CH;
        const int c = (u % CH) ^ (row & 7);
        const int src = b_wave ? r0 + min(row, nr - 1) : min(row, m - 1);
        voff[j] = static_cast<uint32_t>(src * K * 2 + c * 16);
    }

    const int phase = ((tile >> 3) * C::KROT + (tile & 7)) % KT;
    auto issue = [&](int slot, int it) {
        const int kb = it + phase >= KT ? it + phase - KT : it + phase;
        const uint32_t soff = __builtin_amdgcn_readfirstlane(static_cast<uint32_t>(kb * BK * 2));
        if (b_wave) {
            const uint32_t base = lds0 + slot * C::STB;
#pragma unroll
            for (int j = 0; j < C::LB; ++j) {
                const int i = rw + C::WB * j;
                if (j < C::LB - 1 || i < C::IB)
                    dma16<true>(__builtin_amdgcn_readfirstlane(base + i * 1024), voff[j], rsrc, soff);
            }
        } else {
            const uint32_t base = lds_a + slot * C::STA;
#pragma unroll
            for (int j = 0; j < C::LA; ++j) {
                const int i = rw + C::WA * j;
                if (j < C::LA - 1 || i < C::IA)
                    dma16<false>(__builtin_amdgcn_readfirstlane(base + i * 1024), voff[j], rsrc, soff);
            }
        }
    };

    f32x4 acc[MS][NSW];
#pragma unroll
    for (int i = 0; i < MS; ++i)
#pragma unroll
        for (int j = 0; j < NSW; ++j) acc[i][j] = f32x4{0.f, 0.f, 0.f, 0.f};

    const int g = lane >> 4;
    const int rowl = lane & 15;
    const int sw = rowl & 7;
    const uint32_t b_lane = static_cast<uint32_t>(((wn * NSW) * 16 + rowl) * CH * 16);
    const uint32_t a_lane = static_cast<uint32_t>(SB * C::STB + ((wm * MS) * 16 + rowl) * CH * 16);

    const int ahead = b_wave ? SB - 1 : SA - 1;
    const int ring = b_wave ? SB : SA;
    for (int s = 0; s < ahead; ++s) issue(s, s);

    int sb = 0, sa = 0, si = ahead;
    for (int it = 0; it < KT; ++it) {
        if (b_wave) {
            wait_stages<C::LB, SB - 2>(short_wave, KT - 1 - it);
        } else {
            wait_stages<C::LA, SA - 2>(short_wave, KT - 1 - it);
        }
        barrier_lds();
        if (it + ahead < KT) issue(si, it + ahead);
        si = si + 1 == ring ? 0 : si + 1;
        const char* stb = smem + sb * C::STB;
        const char* sta = smem + sa * C::STA;
        // all fragments of the stage are read before the first MFMA, so LDS latency is paid once
        bf16x8 bf[C::KSTEPS][NSW], af[C::KSTEPS][MS];
#pragma unroll
        for (int ks = 0; ks < C::KSTEPS; ++ks) {
            const uint32_t slot = static_cast<uint32_t>(((ks * 4 + g) ^ sw) * 16);
#pragma unroll
            for (int ns = 0; ns < NSW; ++ns)
                bf[ks][ns] = *reinterpret_cast<const bf16x8*>(stb + b_lane + ns * 16 * CH * 16 + slot);
#pragma unroll
            for (int ms = 0; ms < MS; ++ms)
                af[ks][ms] = *reinterpret_cast<const bf16x8*>(sta + a_lane + ms * 16 * CH * 16 + slot);
        }
        __builtin_amdgcn_sched_barrier(0);
#pragma unroll
        for (int ks = 0; ks < C::KSTEPS; ++ks)
#pragma unroll
            for (int ms = 0; ms < MS; ++ms)
#pragma unroll
                for (int ns = 0; ns < NSW; ++ns)
                    acc[ms][ns] = __builtin_amdgcn_mfma_f32_16x16x32_bf16(bf[ks][ns], af[ks][ms], acc[ms][ns], 0, 0, 0);
        sb = sb + 1 == SB ? 0 : sb + 1;
        sa = sa + 1 == SA ? 0 : sa + 1;
    }

    // lane holds out[m = mb * 16 + rowl][n = nb * 16 + g * 4 + r], r < 4, of its blocks
    auto block_live = [&](int ms, int ns) {
        return (wn * NSW + ns) * 16 < nr && (wm * MS + ms) * 16 < m;
    };
    auto store = [&](int ms, int ns, f32x4 v) {
        const int row = (wm * MS + ms) * 16 + rowl;
        const int n = (wn * NSW + ns) * 16 + g * 4;
        if (row < m && n < nr) {
            u32x2 p;
            p.x = pack_bf16x2(v.x, v.y);
            p.y = pack_bf16x2(v.z, v.w);
            *reinterpret_cast<u32x2*>(out + static_cast<size_t>(row) * N + r0 + n) = p;
        }
    };

    if constexpr (SK == 1) {
#pragma unroll
        for (int ms = 0; ms < MS; ++ms)
#pragma unroll
            for (int ns = 0; ns < NSW; ++ns) store(ms, ns, acc[ms][ns]);
    } else {
        // block (ms, ns) belongs to slice (ms * NSW + ns) % SK; the others' partials go through ws
        // in register order, and flags[tile * SK + q] holds this launch's tag once slice q's are out
        const uint64_t tag = lmhead_dispatch_id() * 0x9e3779b97f4a7c15ull +
                             static_cast<uint64_t>(reinterpret_cast<uintptr_t>(__builtin_amdgcn_queue_ptr()));
        f32x4* mine = ws + static_cast<size_t>(tile * SK + kh) * C::NB * C::T + threadIdx.x;
#pragma unroll
        for (int ms = 0; ms < MS; ++ms)
#pragma unroll
            for (int ns = 0; ns < NSW; ++ns) {
                const int blk = ms * NSW + ns;
                if (blk % SK != kh && block_live(ms, ns)) mine[blk * C::T] = acc[ms][ns];
            }
        // the group shares this XCD's L2: stores acknowledged by L2 are visible to it
        wait_vm<0>();
        barrier_lds();
        if (threadIdx.x == 0)
            __hip_atomic_store(flags + tile * SK + kh, tag, __ATOMIC_RELAXED, __HIP_MEMORY_SCOPE_AGENT);
        if (threadIdx.x < SK && threadIdx.x != kh) {
            while (__hip_atomic_load(flags + tile * SK + threadIdx.x, __ATOMIC_RELAXED, __HIP_MEMORY_SCOPE_AGENT) != tag) {
            }
        }
        barrier_lds();
        asm volatile("buffer_inv sc0" ::: "memory");
        const f32x4* grp = ws + static_cast<size_t>(tile * SK) * C::NB * C::T + threadIdx.x;
        // this slice's blocks are kh + SK * o; all loads are issued before the first add
        constexpr int NO = (C::NB + SK - 1) / SK;
        f32x4 own[NO], oth[NO][SK];
#pragma unroll
        for (int o = 0; o < NO; ++o) {
            own[o] = acc[0][0];
#pragma unroll
            for (int q = 0; q < SK; ++q)
                if (q + SK * o < C::NB && kh == q) own[o] = acc[(q + SK * o) / NSW][(q + SK * o) % NSW];
        }
        auto live = [&](int o) {
            const int blk = kh + SK * o;
            return blk < C::NB && block_live(blk / NSW, blk % NSW);
        };
#pragma unroll
        for (int o = 0; o < NO; ++o) {
            if (!live(o)) continue;
#pragma unroll
            for (int q = 0; q < SK; ++q)
                if (q != kh) oth[o][q] = grp[(q * C::NB + kh + SK * o) * C::T];
        }
#pragma unroll
        for (int o = 0; o < NO; ++o) {
            if (!live(o)) continue;
            f32x4 s = kh == 0 ? own[o] : oth[o][0];
#pragma unroll
            for (int q = 1; q < SK; ++q) s += kh == q ? own[o] : oth[o][q];
            store((kh + SK * o) / NSW, (kh + SK * o) % NSW, s);
        }
    }
}

template <class C>
inline void launch(const void* a, const void* b, void* out, float* ws, uint64_t* flags, int m, hipStream_t stream) {
    gemm_kernel<C><<<dim3(C::G), dim3(C::T), 0, stream>>>(static_cast<const __bf16*>(a),
                                                        static_cast<const __bf16*>(b),
                                                        static_cast<__bf16*>(out), reinterpret_cast<f32x4*>(ws),
                                                        flags, m);
}

// 64-bit flag words and fp32 workspace words a launch of C needs
template <class C>
constexpr int64_t flag_words() {
    return C::SK == 1 ? 0 : static_cast<int64_t>(C::G);
}
template <class C>
constexpr int64_t ws_words() {
    return C::SK == 1 ? 0 : static_cast<int64_t>(C::G) * C::NB * C::T * 4;
}

}  // namespace lmhead

// bf16 GEMM for the 25256 x 8192 lm-head slice (vocabulary 202048 / 8):
//   out[m, 25256] = a[m, 8192] @ b[25256, 8192].T, fp32 accumulation, m <= 256.
// Every m here is weight-streaming: b (414 MB) is read once at HBM speed and each workgroup keeps
// its m rows of a in an LDS ring next to b's. Each workgroup owns a contiguous run of b's 8-row
// groups; a's rows past m repeat row m - 1 and are never stored. m > 64 splits K in two within an
// XCD (halving the a traffic per CU); each workgroup of a pair finalizes half of the output blocks,
// adding the other's fp32 partial in fixed order, so results are bitwise reproducible. The tile
// shape is picked per m bucket (gemm_stream.h).
#include <ATen/ATen.h>
#include <ATen/hip/HIPContext.h>
#include <torch/library.h>

#include <initializer_list>
#include <optional>

#include "gemm_stream.h"

namespace {

constexpr int kN = 25256;
constexpr int kK = 8192;

// MT rows of a per tile, G workgroups, SK K slices, SB / SA stages of b / a, WM x WN waves of which
// WA load a, K phase rotation KROT between tiles
template <int MT, int G, int SK, int SB, int SA, int WM, int WN, int WA, int KROT = 8>
using Tile = lmhead::Cfg<kN, kK, MT, G, SK, SB, SA, WM, WN, WA, KROT>;

template <class C>
void launch(const at::Tensor& a, const at::Tensor& b, at::Tensor& out, int m, hipStream_t stream) {
    float* ws = nullptr;
    uint64_t* flags = nullptr;
    at::Tensor scratch;
    if constexpr (C::SK > 1) {
        constexpr int64_t flag_words = lmhead::flag_words<C>();
        constexpr int64_t ws_words = lmhead::ws_words<C>();
        scratch = at::empty({flag_words + ws_words / 2}, a.options().dtype(at::kLong));
        flags = reinterpret_cast<uint64_t*>(scratch.data_ptr<int64_t>());
        ws = reinterpret_cast<float*>(flags + flag_words);
    }
    lmhead::launch<C>(a.data_ptr(), b.data_ptr(), out.data_ptr(), ws, flags, m, stream);
}

void run(const at::Tensor& a, const at::Tensor& b, bool trans_b, const std::optional<at::Tensor>& bias,
         std::optional<at::ScalarType> out_dtype, at::Tensor& out) {
    TORCH_CHECK(trans_b, "b must be [n, k] (trans_b)");
    TORCH_CHECK(!bias.has_value(), "bias is not supported");
    // None (vLLM's tgemm.mm default) means a's dtype
    TORCH_CHECK(out_dtype.value_or(a.scalar_type()) == at::kBFloat16, "bf16 output only");
    TORCH_CHECK(a.dim() == 2 && a.size(1) == kK, "a must be [m, ", kK, "], got ", a.sizes());
    TORCH_CHECK(b.dim() == 2 && b.size(0) == kN && b.size(1) == kK, "b must be [", kN, ", ", kK, "]");
    const int64_t m = a.size(0);
    TORCH_CHECK(out.dim() == 2 && out.size(0) == m && out.size(1) == kN, "out must be [m, ", kN, "]");
    for (const at::Tensor* t : std::initializer_list<const at::Tensor*>{&a, &b, &out}) {
        TORCH_CHECK(t->scalar_type() == at::kBFloat16, "bf16 only, got ", t->scalar_type());
        TORCH_CHECK(t->is_contiguous(), "tensors must be contiguous");
        TORCH_CHECK(t->device() == a.device(), "tensors must share a device");
    }
    TORCH_CHECK(a.is_cuda(), "tensors must be on the GPU");
    TORCH_CHECK(m <= 256, "m must be at most 256, got ", m);
    const auto stream = at::hip::getCurrentHIPStream();
    TORCH_CHECK(stream.device_index() == a.get_device(), "tensors are not on the current device");
    if (m == 0) {
        return;
    }
    const int mi = static_cast<int>(m);
    if (mi <= 32) {
        launch<Tile<32, 243, 1, 5, 3, 1, 2, 1>>(a, b, out, mi, stream);
    } else if (mi <= 48) {
        launch<Tile<48, 243, 1, 4, 5, 3, 1, 1>>(a, b, out, mi, stream);
    } else if (mi <= 64) {
        launch<Tile<64, 243, 1, 4, 4, 4, 1, 1>>(a, b, out, mi, stream);
    } else if (mi <= 80) {
        launch<Tile<80, 256, 2, 3, 3, 5, 2, 2>>(a, b, out, mi, stream);
    } else if (mi <= 96) {
        launch<Tile<96, 256, 2, 3, 3, 1, 7, 2>>(a, b, out, mi, stream);
    } else if (mi <= 112) {
        launch<Tile<112, 256, 2, 3, 3, 7, 2, 2>>(a, b, out, mi, stream);
    } else if (mi <= 128) {
        launch<Tile<128, 256, 2, 4, 3, 4, 2, 2>>(a, b, out, mi, stream);
    } else if (mi <= 144) {
        launch<Tile<144, 256, 2, 4, 3, 1, 7, 2, 16>>(a, b, out, mi, stream);
    } else if (mi <= 160) {
        launch<Tile<160, 256, 2, 4, 3, 1, 7, 2, 16>>(a, b, out, mi, stream);
    } else if (mi <= 176) {
        launch<Tile<176, 256, 2, 3, 3, 1, 7, 2, 16>>(a, b, out, mi, stream);
    } else if (mi <= 192) {
        launch<Tile<192, 256, 2, 3, 3, 4, 2, 2, 16>>(a, b, out, mi, stream);
    } else if (mi <= 208) {
        launch<Tile<208, 256, 2, 2, 3, 1, 7, 2, 16>>(a, b, out, mi, stream);
    } else if (mi <= 224) {
        launch<Tile<224, 256, 2, 2, 3, 7, 1, 2, 16>>(a, b, out, mi, stream);
    } else {
        launch<Tile<256, 256, 2, 2, 3, 4, 2, 2, 16>>(a, b, out, mi, stream);
    }
}

}  // namespace

#define TORCH_LIBRARY_EXPAND(ns, m) TORCH_LIBRARY(ns, m)
TORCH_LIBRARY_EXPAND(TORCH_EXTENSION_NAME, m) {
    m.def("run(Tensor a, Tensor b, bool trans_b, Tensor? bias, ScalarType? out_dtype, Tensor(a!) out) -> ()", &run);
}
